R, C = map(int, input().split())
board = [input() for _ in range(R)]
commands = input()

r = c = 0
for i in range(R):
    for j in range(C):
        if board[i][j] == "S":
            r, c = i, j
move = {"U": (-1, 0), "D": (1, 0), "L": (0, -1), "R": (0, 1)}
visited = {(r, c)}
for ch in commands:
    nr, nc = r + move[ch][0], c + move[ch][1]
    if 0 <= nr < R and 0 <= nc < C and board[nr][nc] != "#":
        r, c = nr, nc
        visited.add((r, c))
print(r + 1, c + 1)
print(len(visited))
